INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-063-129', 'p0269', 'houhanshu', 'a03-063', '《後漢書·卷六十三》', '」鄭玄注曰：「稽，同也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-130', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '鄭玄注論語曰「謂年十五已上」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-131', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '少與鄭玄俱事馬融，能通古今學，好研精而不守章句。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-132', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '」鄭玄注云：「骨曰切，象曰磋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-133', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '脩禮者，應徵有道之人，若鄭玄之徒，陳明洪範，攘服災咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-064-134', 'p0269', 'houhanshu', 'a03-064', '《後漢書·卷六十四》', '」鄭玄注曰：「逢猶大也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-135', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」鄭玄注云：「蕩蕩，法度廢壞之貌也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-136', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '」鄭玄注云：「方叔先與吉甫征伐玁狁，今特往伐蠻荊，皆使來服於宣王之威，美其功之多也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-137', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '行春到高密縣，見鄭玄為鄉佐，知其異器，即召署郡職，遂遣就學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-067-138', 'p0269', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '鄭玄注周禮曰：「木在足曰桎，在手曰梏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-068-139', 'p0269', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '」鄭玄注曰：「倫猶類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-068-140', 'p0269', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '鄭玄注云：「不仁之人，當以風化之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-141', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '東州鄭玄學該古今，玄，北海人，故云東州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-142', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '稍復鳩集吏民為黃巾所誤者男女四萬餘人，更置城邑，立學校，表顯儒術，薦舉賢良鄭玄、彭璆、邴原等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-143', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」案表跋扈，擅誅列侯，遏絕詔命，斷盜貢篚，鄭玄注儀禮曰：「篚，竹器如筐也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-144', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」鄭玄注：「畿，限也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-145', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '山陽郗慮承望風旨，續漢書：「慮字鴻豫，山陽高平人，少受學於鄭玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-146', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '昔國家東遷，文舉盛歎鴻豫名實相副，綜達經學，出於鄭玄，又明司馬法，史記，齊威王使大夫追論古者司馬法。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-147', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」鄭玄注曰：「懿伯，惠伯之叔父也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-070-148', 'p0269', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '今鑾駕旋軫，鄭玄注周禮曰：「軫，輿後橫木也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-071-149', 'p0269', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '彭城相汲廉、北海相孔融、沛相袁忠、太山太守應劭、汝南太守徐璆、前九江太守服虔、博士鄭玄等，敢言之行車騎將軍河南尹莫府：蔡質典職儀曰；「諸州刺史上郡并列卿府，言『敢言之』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-071-150', 'p0269', 'houhanshu', 'a03-071', '《後漢書·卷七十一》', '」鄭玄注云：「鞠，告也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-072-151', 'p0269', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」鄭玄注云：「蕩蕩，法度廢壞之貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-074-152', 'p0269', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」鄭玄注周禮曰：「軿猶屏也，取其自蔽隱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-074-153', 'p0269', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」鄭玄注曰：「槐之言懷也，言懷來人於此欲與謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-076-154', 'p0269', 'houhanshu', 'a03-076', '《後漢書·卷七十六》', '」鄭玄注云：「愛蠶食也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-155', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」鄭玄注云：「中門，於外內為中也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-156', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」鄭玄注月令云：「奄尹，主領奄豎之官者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-157', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '」鄭玄注云：「荊、楊之州，貢金三品。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-158', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '鄭玄注云：「謂所殺者之左耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-078-159', 'p0269', 'houhanshu', 'a03-078', '《後漢書·卷七十八》', '陰陽乖剌，稼穡荒蔬，鄭玄注周禮云：「蔬，草有實者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-079-160', 'p0269', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '融授鄭玄，玄作易注，荀爽又作易傳，自是費氏興，而京氏遂衰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-079-161', 'p0269', 'houhanshu', 'a03-079', '《後漢書·卷七十九上》', '扶風杜林傳古文尚書，林同郡賈逵為之作訓，馬融作傳，鄭玄注解，由是古文尚書遂顯于世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080-162', 'p0269', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '」鄭玄注曰：「謂刻其身以丹青涅之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080-163', 'p0269', 'houhanshu', 'a03-080', '《後漢書·卷八十上》', '」鄭玄注云：「燔魚以祭，變禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080b-164', 'p0269', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」鄭玄注云：「文昌中星。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080b-165', 'p0269', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」鄭玄注云：「小而柄長謂之罼。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-080b-166', 'p0269', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」鄭玄注禮記曰：「絞，蒼黃之色也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-081-167', 'p0269', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '鄭玄注云：「明者，神明之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-081-168', 'p0269', 'houhanshu', 'a03-081', '《後漢書·卷八十一》', '」鄭玄注儀禮云：「如今著幓頭，自項中而前，交額上，却繞髻也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-169', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '』」鄭玄注云：「明素恭肅於鬼神，且順子路之言也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-170', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '鄭玄注云：「由，從也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-171', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '」鄭玄注「詩敦厚，近愚；書知遠，近誣」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-082-172', 'p0269', 'houhanshu', 'a03-082', '《後漢書·卷八十二上》', '清白有節，博學善交，與鄭玄、陳紀等相結。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-083-173', 'p0269', 'houhanshu', 'a03-083', '《後漢書·卷八十三》', '鄭玄注禮記曰：「恇恇，恐也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-084-174', 'p0269', 'houhanshu', 'a03-084', '《後漢書·卷八十四》', '霸子時方耕於野，聞賔至，投耒而歸，鄭玄注禮記云：「耒，耜之上曲者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-086-175', 'p0269', 'houhanshu', 'a03-086', '《後漢書·卷八十六》', '」鄭玄曰：「鍭猶候也，候物而射之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-087-176', 'p0269', 'houhanshu', 'a03-087', '《後漢書·卷八十七》', '鄭玄注云：「不仁之人，當以風化之，疾之已甚，是又使之為亂行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-090-177', 'p0269', 'houhanshu', 'a03-090', '《後漢書·卷九十》', '鄭玄注周禮曰：「毛之縟細者為毳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-091-178', 'p0269', 'houhanshu', 'a03-091', '《二十四史-後漢書-志第一‧律曆上》', '鄭玄曰：「宮數八十一，黃鍾長九寸，九九八十一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-179', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '鄭玄注周禮曰：「天子三推，公五推，卿、諸侯九推，庶人終於千畝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-180', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄曰：「藉之言借也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-181', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄注云：「弗之言祓也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-182', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄注禮記曰：「後王以為禖官嘉祥，而立其祠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-183', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '」鄭玄注禮記曰：「皆年老更事致仕者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-184', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '鄭玄注儀禮曰「狗取擇人」，孟冬亦如之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-094-185', 'p0269', 'houhanshu', 'a03-094', '《二十四史-後漢書-志第四‧禮儀上》', '』」鄭玄注鄉飲酒禮曰：「今郡國十月行鄉飲酒禮，黨正每歲邦索鬼神而祭祀，則以禮屬民而飲酒于序，以正齒位之禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-095-186', 'p0269', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '」鄭玄曰：「䍿，赤皁染羽為之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-095-187', 'p0269', 'houhanshu', 'a03-095', '《二十四史-後漢書-志第五‧禮儀中》', '鄭玄注曰：「此謂民給傜役，若今衞士矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-188', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「夷之言尸也，實冰於槃中，置之尸床之下，所以寒尸也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-189', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「以斂尸者，以大斂焉加之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-190', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄注曰：「袵，小腰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-191', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「方相，放想也，可畏怖之貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-192', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄注旣夕曰：「陳明器，以西行南端為上。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-193', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」筲八盛，容三升，鄭玄注旣夕曰：「筲，畚種類也，其容蓋與簋同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-194', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '鄭玄注旣夕曰：「屑，薑桂之屑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-195', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「翭猶候也，候物而射之矢也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-196', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '巵八，牟八，鄭玄注旣夕曰：「牟，盛湯漿。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-197', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '鄭玄注旣夕曰：「槃匜，盥器也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-198', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '」鄭玄曰：「不懸之也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-096-199', 'p0269', 'houhanshu', 'a03-096', '《二十四史-後漢書-志第六‧禮儀下》', '鄭玄注禮記曰：「芻靈，東茅為人馬，謂之芻靈，神之類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-097-200', 'p0269', 'houhanshu', 'a03-097', '《二十四史-後漢書-志第七‧祭祀上》', '」鄭玄曰：「猶，圖也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-098-201', 'p0269', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」鄭玄曰：「明堂者，明政敎之堂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-098-202', 'p0269', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '孝經云「宗祀文王於明堂以配上帝」，故鄭玄曰「上帝者，天之別名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-098-203', 'p0269', 'houhanshu', 'a03-098', '《二十四史-後漢書-志第八‧祭祀中》', '」鄭玄曰：「六宗，星、辰、司中、司命、風伯、雨師也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-099-204', 'p0269', 'houhanshu', 'a03-099', '《二十四史-後漢書-志第九‧祭祀下》', '大司農鄭玄說古者官有大功，則配食其神。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-205', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '五行傳曰：「田獵不宿，鄭玄注尚書大傳曰：「不宿，不宿禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-206', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」飲食不享，鄭玄曰：「享，獻也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-207', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」注五行稱「鄭玄曰」，皆出注大傳也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-208', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」出入不節，鄭玄曰：「角為天門，房有三道，出入之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-209', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」奪民農時，鄭玄曰：「房、心，農時之候也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-210', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」及有姦謀，鄭玄曰：「亢為朝廷，房、心為明堂，謀事出政之象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-211', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「君行此五者，為逆天東宮之政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-212', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥咎狂，鄭玄曰：「君臣不敬，則倨慢如狂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-213', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥罰恒雨，鄭玄曰：「貌曰木，木主春，春氣生；生氣失則踰其節，故常雨也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-214', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有服妖，鄭玄曰：「服，貌之飾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-215', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有龜孽，鄭玄曰：「龜蟲之生於水而游於春者，屬木。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-216', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有雞禍，鄭玄曰：「雞畜之有冠翼者也，屬貌。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-217', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有下體生上之痾，鄭玄曰：「痾，病也，貌氣失之病也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-218', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有青眚、青祥，鄭玄曰：「青，木色也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-219', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「沴，殄也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-220', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「自正月盡四月為歲之朝，自五月盡八月為歲之中，自九月盡十二月為歲之夕。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-221', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄曰：「二辰謂曰、月也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-222', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '五行傳曰：「好攻戰，鄭玄注曰：「參、伐為武府，攻戰之象。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-223', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」輕百姓，鄭玄注曰：「輕之者，不重民命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-224', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」飾城郭，鄭玄注曰：「昴、畢閒為天街。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-225', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '』」侵邊境，鄭玄曰：「畢主邊兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-226', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」鄭玄注曰：「君行此四者，為逆天西宮之政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-227', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥咎僭，鄭玄曰：「君臣不治，則僭差矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-228', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」厥罰恒陽，鄭玄曰：「金主秋，秋氣殺，殺氣失，故常陽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-229', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '鄭玄曰：「殺氣失，故於人為憂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-230', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有詩妖，鄭玄曰：「詩之言志也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-231', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有介蟲之孽，鄭玄曰：「蝝、螽、蜩、蟬之類，生於火而藏於秋者也，屬金。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-232', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有犬禍，鄭玄曰：「犬畜之以口吠守者，屬言。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-103-233', 'p0269', 'houhanshu', 'a03-103', '《二十四史-後漢書-志第十三‧五行一》', '」時則有口舌之痾，鄭玄曰：「言氣失之病。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-234', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '五行傳曰：「棄法律，鄭玄注尚書大傳曰：「東井主法令也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-235', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」逐功臣，鄭玄曰：「功臣制法律者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-236', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」殺太子，鄭玄曰：「五行火生土，天文以參繼東井，四時以秋代夏，殺太子之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-237', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '』」以妾為妻，鄭玄曰：「軒轅為后妃，屬南宮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-238', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」鄭玄曰：「君行此四者，為逆天南宮之政。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-239', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」鄭玄曰：「君臣不瞭則舒緩矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-240', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」厥罰常燠，鄭玄曰：「視曰火，火主夏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-241', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '鄭玄曰：「長氣失，故於人為疾。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-242', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」時則有草妖，鄭玄曰：「草，視之物可見者，莫衆於草。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-243', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」時則有蠃蟲之孽，鄭玄曰：「蠶螟蟲之類。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-104-244', 'p0269', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '」時則有羊禍，鄭玄曰：「羊畜之遠視者也，屬視。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-245', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '五行傳曰：「簡宗廟，不禱祠，鄭玄注曰：「虛、危為宗廟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-246', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」廢祭祀，鄭玄曰：「牽牛主祭祀之牲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-247', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」逆天時，鄭玄曰：「月在星紀，周以為正，月在玄枵，殷以為正，皆不得四時之正，逆天時之象也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-248', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」鄭玄曰：「君行此四者，為逆天北宮之政也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-249', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '鄭玄曰：「君聽不聦，則是不能謀其事也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-250', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」厥咎急，鄭玄曰：「君臣不謀則急矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-251', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」厥罰恒寒，鄭玄曰：「聽曰水，水主冬，冬氣藏，藏氣失，故常寒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-252', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '鄭玄曰：「藏氣失，故於人為貧。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-253', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有鼓妖，鄭玄曰：「鼓聽之應也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-254', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有魚孽，鄭玄曰：「魚，蟲之生水而游於水者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-255', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有豕禍，鄭玄曰：「豕，畜之居閑衞而聽者也，屬聽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-105-256', 'p0269', 'houhanshu', 'a03-105', '《二十四史-後漢書-志第十五‧五行三》', '」時則有耳痾，鄭玄曰：「聽氣失之病。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-257', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '鄭玄曰：「瞀與思心之咎同耳，故傳曰眊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-258', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」厥罰恒陰，鄭玄曰：「王極象天，天陰養萬物，陰氣失，故常陰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-259', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '鄭玄曰：「天為剛德，剛氣失，故於人為弱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-260', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有射妖，鄭玄曰：「射，王極之度也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-261', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有龍蛇之孽，鄭玄曰：「龍，蟲之生於淵，行於無形，遊於天者也，屬天。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-262', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有馬禍，鄭玄曰：「天行健。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-263', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」時則有下人伐上之痾，鄭玄曰：「夏侯勝說『伐』宜為『代』，書亦或作『代』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-107-264', 'p0269', 'houhanshu', 'a03-107', '《二十四史-後漢書-志第十七‧五行五》', '」鄭玄曰：「亂謂薄食鬬並見，逆謂贏縮反明，經天守舍之類也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-109-265', 'p0269', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '鄭玄詩譜曰：「周公攝政五年，成王宅雒邑，使邵公先相宅，旣成，謂之王城。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-109-266', 'p0269', 'houhanshu', 'a03-109', '《二十四史-後漢書-志第十九‧郡國一》', '鄭玄詩譜曰：「豳者，公劉自邰而出，所徙戎狄之地名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-110-267', 'p0269', 'houhanshu', 'a03-110', '《二十四史-後漢書-志第二十‧郡國二》', '禹貢有外方山，鄭玄毛詩譜云外方之山即嵩也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-112-268', 'p0269', 'houhanshu', 'a03-112', '《二十四史-後漢書-志第二十二‧郡國四》', '三齊記曰：「鄭玄敎授不其山，山下生草大如䪥，葉長一尺餘，堅刃異常，土人名曰康成書帶。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-113-269', 'p0269', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '」鄭玄曰：「西在隴西之西，今謂之八充山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-113-270', 'p0269', 'houhanshu', 'a03-113', '《二十四史-後漢書-志第二十三‧郡國五》', '禮記曰趙武從先大夫於九京，鄭玄曰「晉卿大夫之墓地。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-114-271', 'p0269', 'houhanshu', 'a03-114', '《二十四史-後漢書-志第二十四‧百官一》', '」前書曰「秦官」，鄭玄注月令亦曰「秦官」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-116-272', 'p0269', 'houhanshu', 'a03-116', '《二十四史-後漢書-志第二十六‧百官三》', '周禮天官有司會，鄭玄曰「若今尚書」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-118-273', 'p0269', 'houhanshu', 'a03-118', '《二十四史-後漢書-志第二十八‧百官五》', '」鄭玄曰：「王者存二代而封及五，郊天用天子禮以祭其始祖，行其正朔，此謂通三統也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-274', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄注禮記曰：「此皆天子之禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-275', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄曰：「此皆諸侯之禮也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-276', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄曰：「取幹以冬，取角以秋，絲漆以夏，筋膠未聞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-277', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」自此至弧旌枉矢，皆出周禮，「鄭玄曰」即是周禮注。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-278', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '輿方法地，蓋圓象天；三十輻以象日月；鄭玄曰：「輪象日月者，以其運行也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-279', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」蓋弓二十八以象列星；龍旂九斿，七仞齊軫，鄭玄曰：「軫謂車後橫木。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-280', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」以象大火；鄭玄曰：「交龍為旂，諸侯之所建也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-281', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鳥旟七斿，五仞齊較，鄭玄曰：「較者，車高檻木也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-282', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」以象鶉火；鄭玄曰：「鳥隼為旟，州里之所建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-283', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」熊旗六斿，五仞齊肩，以象參、伐；鄭玄曰：「熊虎為旗，師都之所建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-284', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」龜旐四斿，四仞齊首，以象營室；鄭玄曰：「龜蛇為旐，縣鄙之所建。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-285', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」弧旌枉矢，以象弧也：鄭玄曰：「覲禮曰『侯氏載龍旂弧韣』，則旌旗之屬皆有弧也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-286', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄曰：「王在焉曰路，以玉飾諸末也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-287', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鍚樊纓十有再就，鄭玄曰：「鍚面當盧刻金為之，所謂鏤鍚也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-288', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄曰：「纓，今馬鞅。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-289', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄曰：「七尺為仞，天子之旗高六丈三尺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-290', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '鄭玄以為天子四馬，周禮乘馬有四圉，各養一馬也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-119-291', 'p0269', 'houhanshu', 'a03-119', '《二十四史-後漢書-志第二十九‧輿服上》', '」鄭玄注旣夕曰：「服，車箱也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-292', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」天子備章，鄭玄周禮注曰：「此古天子冕服十二章。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-293', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '鄭玄曰：「華蟲，五色之蟲。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-294', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄注曰：「繅，雜文之名也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-295', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄曰：「謂之端，取其正也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-296', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '禮曰：「朱干玉鏚，鄭玄曰：「朱干，赤大盾也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-297', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '鄭玄箋曰：「佩璲者，以瑞玉為佩，佩之鞙鞙然。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-298', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄詩箋曰：「旣爵命賞賜，而加賜容刀有飾，顯其能制斷也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a03-120-299', 'p0269', 'houhanshu', 'a03-120', '《二十四史-後漢書-志第三十‧輿服下》', '」鄭玄曰：「珈之言加也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-300', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '少受業於鄭玄，建安初為侍中。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-301', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄云：「先正，先臣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-302', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄云：「屆，極也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-303', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄曰：「爰，於也，安隱於其衆也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-001-304', 'p0269', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」鄭玄云：「昏，勉也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-003-305', 'p0269', 'sanguozhi', 'a04-003', '《三國志·魏書三》', '」鄭玄云：「夏后氏以建寅為正，物生色黑；殷以建丑為正，物牙色白；周以建子為正，物萌色赤。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-306', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '帝又問曰：「孔子作彖、象，鄭玄作注，雖聖賢不同，其所釋經義一也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-307', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」俊對曰；「鄭玄合彖、象於經者，欲使學者尋省易了也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-308', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」帝曰：「若鄭玄合之，於學誠便，則孔子曷為不合以了學者乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-309', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '」帝曰：「若聖人以不合為謙，則鄭玄何獨不謙邪？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-310', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '帝問曰：「鄭玄云『稽古同天，言堯同於天也』。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-311', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '伏見故漢大司農北海鄭玄，當時之學，名冠華夏，為世儒宗。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-004-312', 'p0269', 'sanguozhi', 'a04-004', '《三國志·魏書四》', '鄭玄注文王世子曰「三老、五更各一人，皆年老更事致仕者也」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-006-313', 'p0269', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '九州春秋曰：紹延徵北海鄭玄而不禮，趙融聞之曰：「賢人者，君子之望也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-314', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時魯國孔融在郡，教選計當任公卿之才，乃以鄭玄為計掾，彭璆為計吏，原為計佐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-315', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '時鄭玄博學洽聞，注解典籍，故儒雅之士集焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-316', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '昔司空荀爽，家拜光祿，先儒鄭玄，即授司農，若加備禮，庶必可致。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-011-317', 'p0269', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '」鄭玄曰：「耇，老也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-012-318', 'p0269', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '至年二十九，乃結公孫方等就鄭玄受學。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-012-319', 'p0269', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '告高密縣為鄭玄特立一鄉，名為鄭公鄉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-012-320', 'p0269', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '高密鄭玄，稱之鄭公，執子孫禮。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-013-321', 'p0269', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '授學鄭玄之門，人稱東州大儒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-014-322', 'p0269', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '濟又難：鄭玄注祭法云「有虞以上尚德，禘郊祖宗，配用有德，自夏已下，稍用其姓氏」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-014-323', 'p0269', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '臣以為祭法所云，見疑學者乆矣，鄭玄不考正其違而就通其義。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-022-324', 'p0269', 'sanguozhi', 'a04-022', '《三國志·魏書二十二》', '少事馬融，與鄭玄同門相友。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-027-325', 'p0269', 'sanguozhi', 'a04-027', '《三國志·魏書二十七》', '散騎常侍王肅著諸經傳解及論定朝儀，改易鄭玄舊說，而基據持玄義，常與抗衡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-032-326', 'p0269', 'sanguozhi', 'a04-032', '《三國志·蜀書二》', '今臣羣寮以為在昔虞書敦叙九族，庶明勵翼，鄭玄注曰：庶，衆也；勵，作也；叙，次序也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-038-327', 'p0269', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '先主領徐州，辟為從事，鄭玄傳云：玄薦乾於州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-042-328', 'p0269', 'sanguozhi', 'a04-042', '《三國志·蜀書十二》', '著古文易、尚書、毛詩、三禮、左氏傳、太玄指歸，皆依準賈、馬，異於鄭玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-047-329', 'p0269', 'sanguozhi', 'a04-047', '《三國志·吳書二》', '」　鄭玄注曰：「周人卒哭而致事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-053-330', 'p0269', 'sanguozhi', 'a04-053', '《三國志·吳書八》', '逮事鄭玄，後避亂交州，與劉熈考論大義，遂博通五經。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-057-331', 'p0269', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '若乃北海鄭玄，南陽宋忠，雖各立注，忠小差玄而皆未得其門，難以示世。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-057-332', 'p0269', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '」又奏鄭玄解尚書違失事目：「臣聞周公制禮以辨上下，孔子曰『有君臣然後有上下，有上下然後禮義有所錯』，是故尊君卑臣，禮之大司也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a04-057-333', 'p0269', 'sanguozhi', 'a04-057', '《三國志·吳書十二》', '伏見故徵士北海鄭玄所注尚書，以顧命康王執瑁，古『月』似『同』，從誤作『同』，旣不覺定，復訓為杯，謂之酒杯；成王疾困憑几，洮頮為濯，以為澣衣成事，『洮』字虛更作『濯』，以從其非；又古大篆『卯』字讀當為『柳』，古『柳』『卯』同字，而以為昧；『分北三苗』，『北』古『別』字，又訓北，言北猶別也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-011-334', 'p0269', 'jinshu', 'a05-011', '《晉書·卷十一》', '」鄭玄謂以玉為渾儀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-011-335', 'p0269', 'jinshu', 'a05-011', '《晉書·卷十一》', '」鄭玄云：「凡日景於地，千里而差一寸，景尺有五寸者，南戴日下萬五千里也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-016-336', 'p0269', 'jinshu', 'a05-016', '《晉書·卷十六》', '淮南、京房、鄭玄諸儒言律歷，皆上下相生，至蕤賔又重上生大呂，長八寸二百四十三分寸之百四；夷則上生夾鍾，長七寸千一百八十七分寸之千七十五；無射上生中呂，長六寸萬九千六百八十二分寸之萬二千九百七十四：此三呂於司馬遷、班固所生之寸數及分皆倍焉，餘則並同。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-016-337', 'p0269', 'jinshu', 'a05-016', '《晉書·卷十六》', '鄭玄以為鬴方尺，積千寸，比九章粟米法少二升八十一分升之二十二。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0269-a05-017-338', 'p0269', 'jinshu', 'a05-017', '《晉書·卷十七》', '獻帝建安元年，鄭玄受其法，以為窮幽極微，又加注釋焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-068-0', 'p0270', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '與陳留邊讓並善談論，俱有盛名。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-070-1', 'p0270', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '融由是顯名，與平原陶丘洪、陳留邊讓齊聲稱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-074-2', 'p0270', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」故九江太守邊讓，英才儁逸，以直言正色，論不阿諂，身被梟懸之戮，妻孥受灰滅之咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-080b-3', 'p0270', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '張升　趙壹　劉梁　邊讓　酈炎　侯瑾　高彪　張超　禰衡');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-080b-4', 'p0270', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '邊讓字文禮，陳留浚儀人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a03-080b-5', 'p0270', 'houhanshu', 'a03-080b', '《後漢書·卷八十下》', '」竊見令史陳留邊讓，天授逸才，聦明賢智。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-001-6', 'p0270', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，袁忠為沛相，甞欲以法治太祖，沛國桓邵亦輕之，及在兖州，陳留邊讓言議頗侵太祖，太祖殺讓，族其家。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-006-7', 'p0270', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '故九江太守邊讓，英才俊逸，天下知名，以直言正色，論不阿諂，身被梟縣之戮，妻孥受灰滅之咎。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-012-8', 'p0270', 'sanguozhi', 'a04-012', '《三國志·魏書十二》', '融由是名震遠近，與平原陶丘洪、陳留邊讓，並以俊秀，為後進冠蓋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-023-9', 'p0270', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '受學陳留邊讓，讓器異之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0270-a04-028-10', 'p0270', 'sanguozhi', 'a04-028', '《三國志·魏書二十八》', '」　松字叔茂，陳留人，九江太守邊讓外孫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0271-a03-058-0', 'p0271', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '虞詡　傅爕　蓋勳　臧洪');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0271-a03-058-1', 'p0271', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '蓋勳字元固，敦煌廣至人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0272-a03-008-full-0', 'p0272', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0272-a03-008-1', 'p0272', 'houhanshu', 'a03-008', '《後漢書·卷八》', '夏四月，涼州刺史耿鄙討金城賊韓遂，鄙兵大敗，遂寇漢陽，漢陽太守傅燮戰沒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-0', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '八月，大鴻臚橋玄為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-1', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '司徒許訓免，司空橋玄為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-2', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '十二月丁巳，光祿大夫橋玄為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-full-3', 'p0273', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '乙丑，太尉橋玄罷，太中大夫段熲為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-4', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '八月，大鴻臚橋玄為司空。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-5', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '司徒許訓免，司空橋玄為司徒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-6', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '十二月丁巳，光祿大夫橋玄為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-008-7', 'p0273', 'houhanshu', 'a03-008', '《後漢書·卷八》', '乙丑，太尉橋玄罷，太中大夫段熲為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-8', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '李恂　陳禪　龐參　陳龜　橋玄');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-9', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '橋玄字公祖，梁國睢陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-10', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」魏志曰「建安七年，曹公軍譙，遂至浚儀，遣使以太牢祀橋玄，進軍官度」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-11', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '」龐參躬求賢之禮，故民恱其政；橋玄厲邦君之威，而衆失其情。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-051-12', 'p0273', 'houhanshu', 'a03-051', '《後漢書·卷五十一》', '橋玄之舍姜岐，以道不可違，故不得以威力逼也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-056-13', 'p0273', 'houhanshu', 'a03-056', '《後漢書·卷五十六》', '推達名臣橋玄、皇甫規等，為稱職相。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-065-14', 'p0273', 'houhanshu', 'a03-065', '《後漢書·卷六十五》', '光和二年，復代橋玄為太尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a03-074-15', 'p0273', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁字元瑋，橋玄族子，先為兖州刺史，甚有威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-001-16', 'p0273', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '惟梁國橋玄、南陽何顒異焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-001-17', 'p0273', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」魏書曰：太尉橋玄，世名知人，覩太祖而異之，曰：「吾見天下名士多矣，未有若君者也！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-001-18', 'p0273', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」遂至浚儀，治睢陽渠，遣使以太牢祀橋玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-002-19', 'p0273', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '初，漢熹平五年，黃龍見譙，光祿大夫橋玄問太史令單颺：「此何祥也？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0273-a04-002-20', 'p0273', 'sanguozhi', 'a04-002', '《三國志·魏書二》', '十二月，行自譙過梁，遣使以太牢祀故漢太尉橋玄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-062-0', 'p0274', 'houhanshu', 'a03-062', '《後漢書·卷六十二》', '爽見董卓忍暴滋甚，必危社稷，其所辟舉皆取才略之士，將共圖之，亦與司徒王允及卓長史何顒等為內謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-067-1', 'p0274', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '劉淑　李膺　杜密　劉祐　魏朗　夏馥　宗慈　巴肅　范滂　尹勳　蔡衍　羊陟　張儉　岑晊　陳翔　孔昱　苑康　檀𢿭　劉儒　賈彪　何顒');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-067-2', 'p0274', 'houhanshu', 'a03-067', '《後漢書·卷六十七》', '何顒字伯求，南陽襄鄉人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-069-3', 'p0274', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '因復博徵智謀之士龐紀、何顒、荀攸等，與同腹心。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-070-4', 'p0274', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '公業等與侍中伍瓊、卓長史何顒共說卓，以袁紹為勃海太守，以發山東之謀。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-070-5', 'p0274', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '乃與何顒、荀攸共謀殺卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-070-6', 'p0274', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '南陽何顒名知人，見彧而異之，曰：「王佐才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a03-072-7', 'p0274', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '謂忍性屈情，擢用鄭泰、蔡邕、何顒、荀爽等。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-001-8', 'p0274', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '惟梁國橋玄、南陽何顒異焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-006-9', 'p0274', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '侍中周毖、城門校尉伍瓊、議郎何顒等，皆名士也，卓信之，而陰為紹，乃說卓曰：「夫廢立大事，非常人所及。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-010-10', 'p0274', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧年少時，南陽何顒異之，曰：「王佐才也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0274-a04-010-11', 'p0274', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '攸與議郎鄭泰、何顒、侍中种輯、越騎校尉伍瓊等謀曰：「董卓無道，甚於桀紂，天下皆怨之，雖資彊兵，實一匹夫耳。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-001-0', 'p0275', 'houhanshu', 'a03-001', '《後漢書·卷一上》', '甲子，前將軍鄧禹擊更始定國公王匡於安邑，大破之，安邑，縣，屬河東郡，今蒲州縣也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-009-1', 'p0275', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」將作大匠吳脩、越騎校尉王瓌安集關東，後將軍袁術、河內太守王匡各執而殺之，英雄記曰：「匡字公節，太山人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-2', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '新市人王匡、王鳳為平理諍訟，遂推為渠帥，衆數百人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-3', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王常、成丹西入南郡，号下江兵；王匡、王鳳、馬武及其支黨朱鮪、張卬等續漢書「卬」作「印」。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-4', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '悉拜置諸將，以族父良為國三老，王匡為定國上公，王鳳成國上公，朱鮪大司馬，伯升大司徒，陳牧大司空，餘皆九卿、將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-5', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王莽使太師王匡、國將哀章守洛陽。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-6', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '」更始遣定國上公王匡攻洛陽，西屏大將軍申屠建、丞相司直李松攻武關，三輔震動。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-7', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '是月，拔洛陽，生縛王匡、哀章，至，皆斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-8', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '更始乃先封宗室太常將軍劉祉為定陶王，劉賜為宛王，劉慶為燕王，劉歙為元氏王，大將軍劉嘉為漢中王，劉信為汝陰王；後遂立王匡為比陽王，王鳳為宜城王，朱鮪為膠東王，衞尉大將軍張卬為淮陽王，廷尉大將軍王常為鄧王，執金吾大將軍廖湛為穰王，申屠建為平氏王，尚書胡殷為隨王，柱天大將軍李通為西平王，西平，縣，屬汝南郡，故城在今豫州郾城縣南也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-9', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '時李軼、朱鮪擅命山東，王匡、張卬橫暴三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-10', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '時王匡、張卬守河東，為鄧禹所破，還奔長安。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-11', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '及赤眉立劉盆子，更始使王匡、陳牧、成丹、趙萌屯新豐，李松軍掫，掫音子侯反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-12', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '更始復疑王匡、陳牧、成丹與張卬等同謀，乃並召入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-13', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王匡懼，將兵入長安，與張卬等合。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-011-14', 'p0275', 'houhanshu', 'a03-011', '《後漢書·卷十一》', '王莽遣平均公廉丹、太師王匡擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-014-15', 'p0275', 'houhanshu', 'a03-014', '《後漢書·卷十四》', '使宗室劉嘉往誘新市、平林兵王匡、陳牧等，合軍而進，屠長聚及唐子鄉，殺湖陽尉，進拔棘陽，因欲攻宛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-015-16', 'p0275', 'houhanshu', 'a03-015', '《後漢書·卷十五》', '乆之，與王鳳、王匡等起兵雲杜綠林中，聚衆數萬人，以常為偏裨，攻傍縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-17', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '及赤眉西入關，更始使定國上公王匡、襄邑王成丹、抗威將軍劉均及諸將，分據河東、弘農以拒之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-18', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '赤眉衆大集，王匡等莫能當。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-19', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '於是王匡、成丹、劉均等合軍十餘萬，復共擊禹，禹軍不利，樊崇戰死。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-016-20', 'p0275', 'houhanshu', 'a03-016', '《後漢書·卷十六》', '更始諸將王匡、胡殷、成丹等皆詣廣降，與共東歸。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-019-21', 'p0275', 'houhanshu', 'a03-019', '《後漢書·卷十九》', '更始傳曰：「李軼、朱鮪擅命山東，王匡、張卬橫暴三輔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-023-22', 'p0275', 'houhanshu', 'a03-023', '《後漢書·卷二十三》', '王莽末，青、徐賊起，太師王匡匡，王舜之子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-050-full-23', 'p0275', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '堅立二十六年薨，子懷王匡嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-050-24', 'p0275', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '堅立二十六年薨，子懷王匡嗣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-069-25', 'p0275', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '遂西召前將軍董卓屯關中上林苑，又使府掾太山王匡東發其郡強弩，并召東郡太守橋瑁屯城皐，使武猛都尉丁原燒孟津，武猛謂有武蓺而勇猛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-072-26', 'p0275', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '時河內太守王匡屯兵河陽津，英雄記曰：「匡字公節，泰山人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-27', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-28', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '王匡字公節，泰山人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-29', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹與王匡屯河內，伷屯潁川，馥屯鄴，餘軍咸屯酸棗，約盟，遙推紹為盟主。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-30', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹使王匡殺班、瓌、吳循等，海內先賢傳曰：「韓融字元長，潁川人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-31', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」謝承書曰：「班，王匡之妹夫。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a03-074-32', 'p0275', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '時進旣被害，師徒喪沮，臣獨將家兵百餘人，抽戈承明，竦劔翼室，山陽公載記曰：「紹與王匡等并力入端門，於承明堂上格殺中常侍高望等二人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-001-33', 'p0275', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '河內太守王匡、英雄記曰：匡字公節，泰山人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-006-34', 'p0275', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '河內太守王匡遣泰山兵屯河陽津，將以圖卓。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-006-35', 'p0275', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '卓遣執金吾胡母班、將作大匠吳脩齎詔書喻紹，紹使河內太守王匡殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-006-36', 'p0275', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '謝承後漢書曰：班，王匡之妹夫，董卓使班奉詔到河內，解釋義兵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-009-37', 'p0275', 'sanguozhi', 'a04-009', '《三國志·魏書九》', '太守王匡以為從事，將兵拒董卓於盟津。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-023-38', 'p0275', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '太守王匡起兵討董卓，遣諸生於屬縣微伺吏民罪負，便收之，考責錢穀贖罪，稽遲則夷滅宗族，以崇威嚴。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0275-a04-051-39', 'p0275', 'sanguozhi', 'a04-051', '《三國志·吳書六》', '永興元年，乘輿幸鄴，司空東海王越治兵下邳，惠以書干越，詭其姓名，自稱南岳逸民秦祕之，勉以勤王匡世之略，辭義甚美。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-058-0', 'p0276', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '兖州刺史岱、豫州刺史伷、陳留太守邈、東郡太守瑁、橋瑁也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-069-1', 'p0276', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '遂西召前將軍董卓屯關中上林苑，又使府掾太山王匡東發其郡強弩，并召東郡太守橋瑁屯城皐，使武猛都尉丁原燒孟津，武猛謂有武蓺而勇猛者。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-074-2', 'p0276', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-074-3', 'p0276', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁字元瑋，橋玄族子，先為兖州刺史，甚有威惠。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-074-4', 'p0276', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '橋瑁乃詐作三公移書，傳驛州郡，說董卓罪惡，天子危逼，企望義兵，以釋國難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a03-104-5', 'p0276', 'houhanshu', 'a03-104', '《二十四史-後漢書-志第十四‧五行二》', '應劭曰：「關東義兵先起於宋、衞之郊，東郡太守橋瑁負衆怙亂，陵蔑同盟，忿嫉同類，以殞厥命。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a04-001-6', 'p0276', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '東郡太守橋瑁詐作京師三公移書與州郡，陳卓罪惡，云「見逼迫，無以自救，企望義兵，解國患難。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a04-001-7', 'p0276', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '勃海太守袁紹、陳留太守張邈、東郡太守橋瑁、英雄記曰：瑁字元偉，玄族子。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0276-a04-001-8', 'p0276', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '劉岱與橋瑁相惡，岱殺瑁，以王肱領東郡太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a03-074-0', 'p0277', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a03-074-1', 'p0277', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '袁遺字伯業，紹從弟術字公路，汝南汝陽人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a04-001-2', 'p0277', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '山陽太守袁遺、遺字伯業，紹從兄。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0277-a04-006-3', 'p0277', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '袁紹遣袁遺領州，敗散，奔沛國，為兵所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-058-0', 'p0278', 'houhanshu', 'a03-058', '《後漢書·卷五十八》', '豫州刺史孔伷，伷字公緒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-068-1', 'p0278', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '融一往，薦達郡士范冉、韓卓、孔伷等三人，伷音冑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-068-2', 'p0278', 'houhanshu', 'a03-068', '《後漢書·卷六十八》', '旣到官，融往相見，薦范冉為功曹，韓卓為主簿，孔伷為上計吏。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-072-3', 'p0278', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」陳留孔伷為豫州刺史，英雄記伷字公緒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a03-074-4', 'p0278', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '豫州刺史孔伷、兖州刺史劉岱、陳留太守張邈、廣陵太守張超、河內太守王匡、山陽太守袁遺、東郡太守橋瑁、英雄記曰，孔伷字公緒，陳留人也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a04-001-5', 'p0278', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '豫州刺史孔伷、英雄記曰：伷字公緒，陳留人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a04-006-6', 'p0278', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓信任尚書周毖、城門校尉伍瓊等，用其所舉韓馥、劉岱、孔伷、張咨、張邈等出宰州郡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0278-a04-038-7', 'p0278', 'sanguozhi', 'a04-038', '《三國志·蜀書八》', '進用潁川荀爽、韓融、陳紀等為公、卿、郡守，拜尚書韓馥為兾州牧，侍中劉岱為兖州刺史，潁川張咨為南陽太守，陳留孔伷為豫州刺史，東郡張邈為陳留太守，而遷靖巴郡太守，不就，補御史中丞。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-009-0', 'p0279', 'houhanshu', 'a03-009', '《後漢書·卷九》', '袁術遣將孫堅與董卓將胡軫戰於陽人，陽人，聚名，屬河南郡，故城在今汝州梁縣西。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-072-1', 'p0279', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣將胡軫、呂布攻之，布與軫不相能，軍中自驚恐，士卒散亂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-072-2', 'p0279', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '九州春秋曰：「卓以東郡太守胡軫為大督，呂布為騎督。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a03-072-3', 'p0279', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '王允聞之，乃遣卓故將胡軫、徐榮擊之於新豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a04-015-4', 'p0279', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '殷先與司隷校尉胡軫有隙，軫誣搆殺殷。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0279-a04-046-5', 'p0279', 'sanguozhi', 'a04-046', '《三國志·吳書一》', '卓亦遣兵步騎五千迎之，陳郡太守胡軫為大督護，呂布為騎督，其餘步騎將校都督者甚衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0280-a03-010b-full-0', 'p0280', 'houhanshu', 'a03-010b-full', '《後漢書·卷十下》', '卓乃置弘農王於閣上，使郎中令李儒進酖，曰：「服此藥，可以辟惡。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-009-0', 'p0281', 'houhanshu', 'a03-009', '《後漢書·卷九》', '」董卓遣其將牛輔擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-1', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '卓遣中郎將牛輔擊之，不能却。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-2', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '中郎將牛輔屯安邑，其餘中郎將、校尉布在諸縣，以禦山東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-3', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '初，卓以牛輔子壻，素所親信，使以兵屯陝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-4', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '其後牛輔營中無故大驚，輔懼，乃齎金寶踰城走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-5', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '牛輔旣敗，衆無所依，欲各散去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-6', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」牛輔屯陝，詡在輔軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a03-072-7', 'p0281', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '又以故牛輔部曲董承為安集將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a04-006-8', 'p0281', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，卓女壻中郎將牛輔典兵別屯陝，分遣校尉李傕、郭汜、張濟略陳留、潁川諸縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0281-a04-010-9', 'p0281', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '卓壻中郎將牛輔屯陝，詡在輔軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0282-a04-006-0', 'p0282', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '近董公之彊，明將軍目所見，內有王公以為內主，外有董旻、承、璜以為鯁毒，呂布受恩而反圖之，斯須之間，頭縣竿端，此有勇而無謀也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-009-0', 'p0283', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三年夏四月，遣謁者裴茂率中郎將段煨討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-1', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」乃使東中郎將董越屯黽池，中郎將段煨屯華陰，典略曰：「煨在華陰，特修農事。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-2', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」寧輯將軍段煨乃具服御及公卿以下資儲，請帝幸其營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-3', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '侍中种輯素與定親，乃言曰：『段煨欲反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-4', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '李傕、郭汜旣悔令天子東，乃來救段煨，因欲劫帝而西，楊定為汜所遮，亡奔荊州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-5', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '三年，使謁者僕射裴茂詔關中諸將段煨等討李傕，夷三族。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-6', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '」以段煨為安南將軍，封閺鄉侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a03-072-7', 'p0283', 'houhanshu', 'a03-072', '《後漢書·卷七十二》', '後徵段煨為大鴻臚，病卒。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a04-010-8', 'p0283', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '是時將軍段煨屯華陰，典略稱煨在華陰時，脩農事，不虜略。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0283-a04-013-9', 'p0283', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '興平中，關中擾亂，與兄季中依將軍段煨。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0284-a04-007-0', 'p0284', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '建安元年六月夜半時，布將河內郝萌反，將兵入布所治下邳府，詣廳事閤外，同聲大呼攻閤，閤堅不得入。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0284-a04-007-1', 'p0284', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '布從郝萌反後，更疏順。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0285-a04-007-0', 'p0285', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '萌將曹性反萌，與對戰，萌刺傷性，性斫萌一臂。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0286-a04-001-0', 'p0286', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '月餘，布將宋憲、魏續等執陳宮，舉城降，生禽布、宮，皆殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0286-a04-007-1', 'p0286', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0287-a04-001-0', 'p0287', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '月餘，布將宋憲、魏續等執陳宮，舉城降，生禽布、宮，皆殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0287-a04-007-1', 'p0287', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0287-a04-007-2', 'p0287', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '以魏續有外內之親，悉奪順所將兵以與續。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-018-0', 'p0288', 'houhanshu', 'a03-018', '《後漢書·卷十八》', '子哀侯成嗣，為奴所殺。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-050-full-1', 'p0288', 'houhanshu', 'a03-050-full', '《後漢書·卷五十》', '匡立十一年薨，無子，順帝封匡弟孝陽亭侯成為梁王，是為夷王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-050-2', 'p0288', 'houhanshu', 'a03-050', '《後漢書·卷五十》', '匡立十一年薨，無子，順帝封匡弟孝陽亭侯成為梁王，是為夷王。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a03-075-3', 'p0288', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '其將侯成使客牧其名馬，而客策之以叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a04-007-4', 'p0288', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '太祖塹圍之三月，上下離心，其將侯成、宋憲、魏續縛陳宮，將其衆降。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0288-a04-007-5', 'p0288', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '九州春秋曰：初，布騎將侯成遣客牧馬十五匹，客悉驅馬去，向沛城，欲歸劉備。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-0', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '潁川郭圖、淳于瓊曰：九州春秋圖字公則。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-1', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」郭圖、審配曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-2', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」紹乃分授所統為三都督，使授及郭圖、淳于瓊各典一軍，未及行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-3', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」遂以疾退，紹不許而意恨之，復省其所部，并屬郭圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-4', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '』郭圖曰：『郃計非也，不如攻其本營。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-5', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a03-074-6', 'p0289', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-001-7', 'p0289', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，紹遣郭圖、淳于瓊、顏良攻東郡太守劉延於白馬，紹引兵至黎陽，將渡河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-8', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，天子之立非紹意，及在河東，紹遣潁川郭圖使焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-9', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '郭圖、淳于瓊曰：「漢室陵遲，為日乆矣，今欲興之，不亦難乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-10', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '案此書稱郭圖之計，則與本傳違也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-11', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」審配、郭圖曰：「兵書之法，十圍五攻，敵則能戰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-12', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃分監軍為三都督，使授及郭圖、淳于瓊各典一軍，遂合而南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-13', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹恨之，乃省其所部兵屬郭圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-14', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-15', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '旣劫於郭圖，亦以兵鋒累交，遂戰不解。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-006-16', 'p0289', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，譚之去，皆呼辛毗、郭圖家得出，而辛評家獨被收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-010-17', 'p0289', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧弟諶及同郡辛評、郭圖，皆為紹所任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-013-18', 'p0289', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '舉孝廉，謝承漢書曰：南陽陰脩為潁川太守，以旌賢擢俊為務，舉五官掾張仲方正，察功曹鍾繇、主簿荀彧、主記掾張禮、賊曹掾杜祐、孝廉荀攸、計吏郭圖為吏，以光國朝。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-014-19', 'p0289', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初，北見袁紹，謂紹謀臣辛評、郭圖曰：「夫智者審於量主，故百舉百全而功名可立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-014-20', 'p0289', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '有郭圖、逢紀為之謀臣，必交鬬其閒，還相離也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-017-21', 'p0289', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '」郭圖曰：「郃計非也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-017-22', 'p0289', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '至如此傳，為紹軍先潰，懼郭圖之譖，然後歸太祖，為參錯不同矣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0289-a04-025-23', 'p0289', 'sanguozhi', 'a04-025', '《三國志·魏書二十五》', '郭圖說譚曰：「今將軍國小兵少，糧匱勢弱，顯甫之來，久則不敵。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-070-0', 'p0290', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '審配、逢紀盡忠之臣任其事，配字正南，魏郡人。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-070-1', 'p0290', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-2', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹客逢紀謂紹曰：英雄記曰：「紀字元圖。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-3', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-4', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '先賢行狀曰：「紹謂逢紀曰：『兾州人聞吾軍敗，皆當念吾；唯田別駕前諫止吾，與衆不同，吾亦慙之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-5', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a03-074-6', 'p0290', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-7', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '英雄記曰：逢紀說紹曰：「將軍舉大事而仰人資給，不據一州，無以自全。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-8', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-9', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '逢紀憚豐亮直，數讒之於紹，紹遂忌豐。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-10', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」紹謂逢紀曰：「兾州人聞吾軍敗，皆當念吾，唯田別駕前諫止吾，與衆不同，吾亦慙見之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-11', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-12', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '譚軍黎陽，尚少與譚兵，而使逢紀從譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-006-13', 'p0290', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '是時凶臣逢紀，妄畫蛇足，曲辭諂媚，交亂懿親，將軍奮赫然之怒，誅不旋時，我將軍亦奉命承旨，加以淫刑。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-010-14', 'p0290', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-010-15', 'p0290', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配專而無謀，逢紀果而自用，此二人留知後事，若攸家犯其法，必不能縱也，不縱，攸必為變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0290-a04-014-16', 'p0290', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '有郭圖、逢紀為之謀臣，必交鬬其閒，還相離也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a03-074-0', 'p0291', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '護軍逢紀與配不睦，英雄記曰：「審配任用，與紀不睦，辛評、郭圖皆比於譚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a03-074-1', 'p0291', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」未及定嗣，逢紀、審配宿以驕侈為譚所病，辛評、郭圖皆比於譚而與配、紀有隙。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-006-2', 'p0291', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '審配、逢紀與辛評、郭圖爭權，配、紀與尚比，評、圖與譚比。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-006-3', 'p0291', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '初，譚之去，皆呼辛毗、郭圖家得出，而辛評家獨被收。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-010-4', 'p0291', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '彧弟諶及同郡辛評、郭圖，皆為紹所任。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0291-a04-014-5', 'p0291', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '初，北見袁紹，謂紹謀臣辛評、郭圖曰：「夫智者審於量主，故百舉百全而功名可立也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-009-0', 'p0292', 'houhanshu', 'a03-009', '《後漢書·卷九》', '三月，曹操破高幹於并州，獲之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-049-1', 'p0292', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '并州刺史高幹，袁紹甥也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-049-2', 'p0292', 'houhanshu', 'a03-049', '《後漢書·卷四十九》', '魏志曰：「高幹叛，欲南奔荊州，上洛都尉王琰捕斬之」也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-074-3', 'p0292', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹乃使外甥陳留高幹及潁川荀諶等說馥曰：魏志云諶，荀彧之弟。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-074-4', 'p0292', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」於是以中子熙為幽州刺史，外甥高幹為并州刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a03-074-5', 'p0292', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」并州越太行，紹甥高幹為并州刺史，故言越太行山而來助。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-001-6', 'p0292', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '初，袁紹以甥高幹領并州牧，公之拔鄴，幹降，遂以為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-001-7', 'p0292', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '濟師洪河，拓定四州，袁譚、高幹，咸梟其首，海盜奔迸，黑山順軌，此又君之功也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-8', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會卓西入關，紹還軍延津，因馥惶遽，使陳留高幹、頴川荀諶等說馥曰：「公孫瓚乘勝來向南，而諸郡應之，袁車騎引軍東向，此其意不可知，竊為將軍危之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-9', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '又以中子熈為幽州，甥高幹為并州。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-10', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '高幹以并州降，復以幹為刺史。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-11', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」高幹叛，執上黨太守，舉兵守壺口關。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-006-12', 'p0292', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '典略曰：上洛都尉王琰獲高幹，以功封侯；其妻哭於室，以為琰富貴將更娶妾媵而奪己愛故也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-010-13', 'p0292', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖渡河，擊紹子譚、尚，而高幹、郭援侵略河東，關右震動，鍾繇帥馬騰等擊破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-010-14', 'p0292', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '太祖之征袁尚也，高幹密遣兵謀襲鄴，衍逆覺，盡誅之，以功封列侯。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-011-15', 'p0292', 'sanguozhi', 'a04-011', '《三國志·魏書十一》', '并州牧高幹表除樂平令，不就，徙遁常山，門徒且數百人，遷居任縣。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-013-16', 'p0292', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '濟水未半，擊，大破之，司馬彪戰略曰：袁尚遣高幹、郭援將兵數萬人，與匈奴單于寇河東，遣使與馬騰、韓遂等連和，騰等陰許之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-013-17', 'p0292', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '今曹公與袁氏相持，而高幹、郭援獨制河東，曹公雖有萬全之計，不能禁河東之不危也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-013-18', 'p0292', 'sanguozhi', 'a04-013', '《三國志·卷十三‧魏書十三》', '其後河東衞固作亂，與張晟、張琰及高幹等並為寇，繇又率諸將討破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-015-19', 'p0292', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '時承高幹荒亂之餘，胡狄在界，張雄跋扈，吏民亡叛，入其部落；兵家擁衆，作為寇害，更相扇動，往往棊跱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-015-20', 'p0292', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '袁尚拒太祖於黎陽，遣所置河東太守郭援、并州刺史高幹及匈奴單于取平陽，發使西與關中諸將合從。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-015-21', 'p0292', 'sanguozhi', 'a04-015', '《三國志·魏書十五》', '高幹之反，張琰將舉兵以應之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-016-22', 'p0292', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '太祖旣定河北，而高幹舉并州反。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-016-23', 'p0292', 'sanguozhi', 'a04-016', '《三國志·魏書十六》', '會白騎攻東垣，高幹入濩澤，上黨諸縣殺長吏，弘農執郡守，固等密調兵未至。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-017-24', 'p0292', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '進別征高幹，從北道入上黨，回出其後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-018-25', 'p0292', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '從圍鄴，鄴定，與樂進圍高幹於壺關，擊管承於長廣，皆破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-018-26', 'p0292', 'sanguozhi', 'a04-018', '《三國志·魏書十八》', '建安中，太祖討袁譚、尚於黎陽，譚遣郭援、高幹等略取河東，太祖使鍾繇率關中諸將討之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-021-27', 'p0292', 'sanguozhi', 'a04-021', '《三國志·魏書二十一》', '并州刺史高幹素貴有名，招致四方游士，多歸焉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-023-28', 'p0292', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '并州刺史高幹表為騎都尉，林辭不受。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-023-29', 'p0292', 'sanguozhi', 'a04-023', '《三國志·魏書二十三》', '會以建策捕高幹，又追錄前討郭援功，封武鄉侯，遷弘農太守。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-024-30', 'p0292', 'sanguozhi', 'a04-024', '《三國志·魏書二十四》', '高幹旣降，頃之以并州叛。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-026-31', 'p0292', 'sanguozhi', 'a04-026', '《三國志·魏書二十六》', '時尚外兄高幹為并州刺史，招以并州左有恒山之險，右有大河之固，帶甲五萬，北阻彊胡，勸幹迎尚，并力觀變。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0292-a04-036-32', 'p0292', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '騰遣超隨繇討郭援、高幹於平陽，超將龐德親斬援首。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-070-0', 'p0293', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」顏良、文醜勇冠三軍，統其兵，殆難克乎？');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-070-1', 'p0293', 'houhanshu', 'a03-070', '《後漢書·卷七十》', '」彧曰：「紹兵雖多而法不整，田豐剛而犯上，許攸貪而不正，審配專而無謀，逢紀果而自用，顏良、文醜匹夫之勇，可一戰而擒也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-074-2', 'p0293', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '於是簡精兵十萬，騎萬匹，欲出攻許，以審配、逢紀統軍事，田豐、荀諶及南陽許攸為謀主，顏良、文醜為將帥。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-074-3', 'p0293', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '乃先遣顏良攻曹操別將劉延於白馬，白馬，縣，屬東郡，今滑州縣也，故城在今縣東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a03-074-4', 'p0293', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '曹操遂救劉延，擊顏良斬之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-001-5', 'p0293', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，紹遣郭圖、淳于瓊、顏良攻東郡太守劉延於白馬，紹引兵至黎陽，將渡河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-001-6', 'p0293', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '公到延津，若將渡兵向其後者，紹必西應之，然後輕兵襲白馬，掩其不備，顏良可禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-006-7', 'p0293', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '衆數十萬，以審配、逢紀統軍事，田豐、荀諶、許攸為謀主，顏良、文醜為將率，簡精卒十萬，騎萬匹，將攻許。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-006-8', 'p0293', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹進軍黎陽，遣顏良攻劉延於白馬。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-9', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '孔融謂彧曰：「紹地廣兵彊；田豐、許攸，智計之士也，為之謀；審配、逢紀，盡忠之臣也，任其事；顏良、文醜，勇冠三軍，統其兵：殆難克乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-10', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '顏良、文醜，一夫之勇耳，可一戰而禽也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-11', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '審配以許攸家不法，收其妻子，攸怒叛紹；顏良、文醜臨陣授首；田豐以諫見誅：皆如彧所策。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-010-12', 'p0293', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '後從救劉延於白馬，攸畫策斬顏良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-014-13', 'p0293', 'sanguozhi', 'a04-014', '《三國志·魏書十四》', '袁紹遣將顏良攻東郡，又徙昭為魏郡太守，從討良。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-017-14', 'p0293', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '從破劉備，又從破顏良，拔白馬，進至延津，破文醜，拜偏將軍。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-036-15', 'p0293', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '紹遣大將軍顏良攻東郡太守劉延於白馬，曹公使張遼及羽為先鋒擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0293-a04-036-16', 'p0293', 'sanguozhi', 'a04-036', '《三國志·蜀書六》', '」及羽殺顏良，曹公知其必去，重加賞賜。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-008-full-0', 'p0295', 'houhanshu', 'a03-008-full', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-008-1', 'p0295', 'houhanshu', 'a03-008', '《後漢書·卷八》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八校，皆統於蹇碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-069-2', 'p0295', 'houhanshu', 'a03-069', '《後漢書·卷六十九》', '是時置西園八校尉，以小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎都尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍校尉，淳于瓊為佐軍校尉，又有左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-3', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '樂資山陽公載記曰：「小黃門蹇碩為上軍校尉，虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融為助軍左校尉，馮芳為助軍右校尉，諫議大夫夏牟為左校尉，淳于瓊為右校尉：凡八人，謂之西園軍，皆統於碩。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-4', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '潁川郭圖、淳于瓊曰：九州春秋圖字公則。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-5', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '」紹乃分授所統為三都督，使授及郭圖、淳于瓊各典一軍，未及行。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-6', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹遣淳于瓊等將兵萬餘人北迎粮運。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a03-074-7', 'p0295', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會攸家犯法，審配收繫之，攸不得志，遂奔曹操，而說使襲取淳于瓊等，瓊等時宿在烏巢，烏巢，地名，在滑州酸棗城東。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-8', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '二月，紹遣郭圖、淳于瓊、顏良攻東郡太守劉延於白馬，紹引兵至黎陽，將渡河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-9', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '紹若有十倍之衆，理應當悉力圍守，使出入斷絕，而公使徐晃等擊其運車，公又自出擊淳于瓊等，揚旌往還，曾無抵閡，明紹力不能制，是不得甚少，二也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-10', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '」冬十月，紹遣車運穀，使淳于瓊等五人將兵萬餘人送之，宿紹營北四十里。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-001-11', 'p0295', 'sanguozhi', 'a04-001', '《三國志·魏書一》', '輙勒兵馬，與戰官渡，乘聖朝之威，得斬紹大將淳于瓊等八人首，遂大破潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-006-12', 'p0295', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '郭圖、淳于瓊曰：「漢室陵遲，為日乆矣，今欲興之，不亦難乎！');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-006-13', 'p0295', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '乃分監軍為三都督，使授及郭圖、淳于瓊各典一軍，遂合而南。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-006-14', 'p0295', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '會紹遣淳于瓊等將兵萬餘人北迎運車，沮授說紹：「可遣將蔣奇別為支軍於表，以斷曹公之鈔。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-008-15', 'p0295', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '靈帝紀曰：以虎賁中郎將袁紹為中軍校尉，屯騎校尉鮑鴻為下軍校尉，議郎曹操為典軍校尉，趙融、馮芳為助軍校尉，夏牟、淳于瓊為左右校尉。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-010-16', 'p0295', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '遂以奇兵襲紹別屯，斬其將淳于瓊等，紹退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-010-17', 'p0295', 'sanguozhi', 'a04-010', '《三國志·魏書十》', '會許攸來降，言紹遣淳于瓊等將萬餘兵迎運糧，將驕卒惰，可要擊也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-017-18', 'p0295', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '渡河攻獲嘉，還，從擊袁紹於官渡，力戰，斬紹將淳于瓊。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-017-19', 'p0295', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '紹遣將淳于瓊等督運屯烏巢，太祖自將急擊之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0295-a04-017-20', 'p0295', 'sanguozhi', 'a04-017', '《三國志·魏書十七》', '臣松之案武紀及袁紹傳並云袁紹使張郃、高覽攻太祖營，郃等聞淳于瓊破，遂來降，紹衆於是大潰。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-009-0', 'p0296', 'houhanshu', 'a03-009', '《後漢書·卷九》', '是歲，袁紹遣將麴義與公孫瓉戰於鮑丘，鮑丘，水名，出北塞中，南流經九莊嶺東，俗謂之大榆河。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-073-1', 'p0296', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '烏桓峭王感虞恩德，率種人及鮮卑七千餘騎，共輔南迎虞子和，與袁紹將麴義合兵十萬，共攻瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-073-2', 'p0296', 'houhanshu', 'a03-073', '《後漢書·卷七十三》', '相持歲餘，麴義軍糧盡，士卒飢困，餘衆數千人退走。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-3', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '明年，馥將麴義反畔，馥與戰失利。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-4', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '紹先令麴義領精兵八百，強弩千張，以為前登。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-5', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '麴義追至界橋，九州春秋曰：「還屯廣宗界橋。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-6', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '會麴義來迎，騎乃散退。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a03-074-7', 'p0296', 'houhanshu', 'a03-074', '《後漢書·卷七十四上》', '麴義自恃有功，驕縱不軌，紹召殺之，而并其衆。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-006-8', 'p0296', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '紹令麴義以八百兵為先登，彊弩千張夾承之，紹自以步兵數萬結陣於後。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-006-9', 'p0296', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '瓚騎不知是紹，亦稍引郤；會麴義來迎，乃散去。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-006-10', 'p0296', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '」麴義後恃功而驕恣，紹乃殺之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-11', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '紹軍廣川，令將麴義先登與瓚戰，生禽綱。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-12', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '袁紹又遣麴義及虞子和，將兵與輔合擊瓚。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-13', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '前以西山陸梁，出兵平討，會麴義餘殘，畏誅逃命，故遂住大軍，分兵撲蕩，此兵孤之前行，乃界橋搴旗拔壘，先登制敵者也。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0296-a04-008-14', 'p0296', 'sanguozhi', 'a04-008', '《三國志·魏書八》', '單于執楊與俱去，紹使將麴義追擊於鄴南，破之。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0297-a03-075-0', 'p0297', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術遣將紀靈等步騎三萬以攻備，備求救於布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0297-a04-007-1', 'p0297', 'sanguozhi', 'a04-007', '《三國志·魏書七》', '術遣將紀靈等步騎三萬攻備，備求救於布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a03-075-0', 'p0298', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術大怒，遣其將張勳、橋蕤攻布，大敗而還。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a03-075-1', 'p0298', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '術聞大駭，即走度淮，留張勳、橋蕤於蘄陽，水經曰：「蘄水出江夏蘄春縣北山。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a03-075-2', 'p0298', 'houhanshu', 'a03-075', '《後漢書·卷七十五》', '袁術怒布殺韓胤，遣其大將張勳、橋蕤等與韓暹、楊奉連埶，步騎數萬，七道攻布。');
INSERT INTO excerpts (id, person_id, work, source, citation, quote) VALUES ('p0298-a04-006-3', 'p0298', 'sanguozhi', 'a04-006', '《三國志·魏書六》', '以張勳、橋蕤等為大將軍。');
